RAMCHANDRA_KRIPALU = [
 (P,"श्री रामचन्द्र कृपालु भजु मन, हरण भवभय दारुणं।\nनवकंज लोचन कंज मुख, कर कंज पद कंजारुणं॥","हे मन, कृपालु श्रीरामचंद्र का भजन कर, जो संसार के भयानक डर को हरते हैं। उनकी आँखें नए कमल जैसी, मुख कमल जैसा और हाथ-पैर लाल कमल जैसे हैं।"),
 (P,"कन्दर्प अगणित अमित छवि, नव नील नीरद सुन्दरं।\nपटपीत मानहुं तड़ित रुचि, शुचि नौमि जनक सुतावरं॥","उनकी छवि अनगिनत कामदेवों से भी सुंदर है, नए नीले बादल जैसी; पीला वस्त्र बिजली जैसा चमकता है — ऐसे सीता-पति को मैं नमन करता हूँ।"),
 (P,"भजु दीनबन्धु दिनेश दानव, दैत्यवंश निकन्दनं।\nरघुनन्द आनन्दकन्द कोशल, चन्द दशरथ नन्दनं॥","दीनों के मित्र, असुरों के वंश का नाश करने वाले सूर्य जैसे, आनंद के मूल, कोशल के चंद्रमा दशरथ-नंदन का भजन कर।"),
 (P,"सिर मुकुट कुंडल तिलक चारु, उदारु अंग विभूषणं।\nआजानुभुज शर चाप धर, संग्राम जित खरदूषणं॥","सिर पर मुकुट, कानों में कुंडल, सुंदर तिलक और अंगों पर गहने हैं; घुटनों तक लंबी भुजाओं में धनुष-बाण है, जिन्होंने खर-दूषण को युद्ध में जीता।"),
 (P,"इति वदति तुलसीदास, शंकर शेष मुनि मन रंजनं।\nमम हृदय कंज निवास कुरु, कामादि खलदल गंजनं॥","तुलसीदास कहते हैं — शिव, शेष और मुनियों के मन को आनंद देने वाले प्रभु, काम आदि दुष्टों का नाश करने वाले, मेरे हृदय-कमल में निवास कीजिए।"),
]

RUDRASHTAKAM = [
 (S,"नमामीशमीशान निर्वाणरूपं।\nविभुं व्यापकं ब्रह्मवेदस्वरूपं॥\nनिजं निर्गुणं निर्विकल्पं निरीहं।\nचिदाकाशमाकाशवासं भजेऽहं॥","मैं ईशान शिव को नमन करता हूँ, जो मोक्ष स्वरूप, सर्वव्यापक, ब्रह्म और वेद स्वरूप हैं; जो गुणों और इच्छाओं से परे, चेतना रूपी आकाश में बसने वाले हैं — मैं उनका भजन करता हूँ।"),
 (S,"निराकारमोंकारमूलं तुरीयं।\nगिरा ज्ञान गोतीतमीशं गिरीशं॥\nकरालं महाकाल कालं कृपालं।\nगुणागार संसारपारं नतोऽहं॥","जो निराकार हैं, ॐकार के मूल हैं, वाणी-ज्ञान-इंद्रियों से परे हैं, कैलाशपति हैं; जो काल के भी काल महाकाल होकर भी कृपालु हैं — गुणों के धाम, संसार से पार लगाने वाले को मैं नमन करता हूँ।"),
 (S,"तुषाराद्रि संकाश गौरं गभीरं।\nमनोभूत कोटि प्रभा श्री शरीरं॥\nस्फुरन्मौलि कल्लोलिनी चारु गंगा।\nलसद्भालबालेन्दु कंठे भुजंगा॥","जो हिमालय जैसे गोरे और गंभीर हैं, जिनके शरीर में करोड़ों कामदेवों की आभा है; सिर पर लहराती गंगा, माथे पर बाल-चंद्रमा और गले में सर्प शोभा देते हैं।"),
 (S,"चलत्कुण्डलं भ्रू सुनेत्रं विशालं।\nप्रसन्नाननं नीलकंठं दयालं॥\nमृगाधीशचर्माम्बरं मुण्डमालं।\nप्रियं शंकरं सर्वनाथं भजामि॥","हिलते कुंडल, सुंदर भौंहें और बड़ी आँखें, प्रसन्न मुख, नीला कंठ, दयालु स्वभाव, सिंह-चर्म के वस्त्र और मुंडमाला — ऐसे प्रिय शंकर, सबके नाथ का मैं भजन करता हूँ।"),
 (S,"प्रचण्डं प्रकृष्टं प्रगल्भं परेशं।\nअखण्डं अजं भानुकोटिप्रकाशं॥\nत्रयः शूल निर्मूलनं शूलपाणिं।\nभजेऽहं भवानीपतिं भावगम्यं॥","प्रचंड, श्रेष्ठ, तेजस्वी परमेश्वर, अखंड, अजन्मा, करोड़ों सूर्यों जैसे प्रकाश वाले; तीनों तापों को जड़ से मिटाने वाले त्रिशूलधारी, भाव से पाए जाने वाले भवानीपति का मैं भजन करता हूँ।"),
 (S,"कलातीत कल्याण कल्पान्तकारी।\nसदा सज्जनानन्ददाता पुरारी॥\nचिदानन्द संदोह मोहापहारी।\nप्रसीद प्रसीद प्रभो मन्मथारी॥","जो समय से परे, कल्याण स्वरूप, कल्प का अंत करने वाले, सज्जनों को सदा आनंद देने वाले त्रिपुरारी हैं; चेतना और आनंद के सागर, मोह हरने वाले कामदेव के शत्रु — हे प्रभु, प्रसन्न होइए।"),
 (S,"न यावत् उमानाथ पादारविन्दं।\nभजन्तीह लोके परे वा नराणां॥\nन तावत्सुखं शान्ति सन्तापनाशं।\nप्रसीद प्रभो सर्वभूताधिवासं॥","हे उमानाथ, जब तक मनुष्य आपके चरण-कमलों का भजन नहीं करते, तब तक इस लोक या परलोक में उन्हें सुख, शांति और दुखों से छुटकारा नहीं मिलता। सब प्राणियों में बसने वाले प्रभु, प्रसन्न होइए।"),
 (S,"न जानामि योगं जपं नैव पूजां।\nनतोऽहं सदा सर्वदा शम्भु तुभ्यं॥\nजरा जन्म दुःखौघ तातप्यमानं।\nप्रभो पाहि आपन्नमामीश शम्भो॥","मैं न योग जानता हूँ, न जप, न पूजा; हे शंभु, मैं सदा आपको नमन करता हूँ। बुढ़ापे, जन्म और दुखों से तपते हुए मुझ शरणागत की, हे प्रभु शंभु, रक्षा कीजिए।"),
 (D,"रुद्राष्टकमिदं प्रोक्तं विप्रेण हरतोषये।\nये पठन्ति नरा भक्त्या तेषां शम्भुः प्रसीदति॥","शिव को प्रसन्न करने के लिए ब्राह्मण द्वारा कहा गया यह रुद्राष्टक जो भक्ति से पढ़ते हैं, उन पर शंभु प्रसन्न होते हैं।"),
]

NIRVANA_SHATAKAM = [
 (S,"मनोबुद्ध्यहंकारचित्तानि नाहं\nन च श्रोत्रजिह्वे न च घ्राणनेत्रे।\nन च व्योम भूमिर्न तेजो न वायुः\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मैं मन, बुद्धि, अहंकार या चित्त नहीं हूँ; न कान, जीभ, नाक या आँखें हूँ; न आकाश, धरती, अग्नि या वायु हूँ — मैं चेतना और आनंद रूप शिव हूँ, शिव हूँ।"),
 (S,"न च प्राणसंज्ञो न वै पञ्चवायुः\nन वा सप्तधातुः न वा पञ्चकोशः।\nन वाक्पाणिपादं न चोपस्थपायु\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मैं न प्राण हूँ, न पाँच वायु, न सात धातुएँ, न पाँच कोश; न वाणी, हाथ, पैर या कोई कर्मेंद्रिय — मैं चेतना और आनंद रूप शिव हूँ।"),
 (S,"न मे द्वेषरागौ न मे लोभमोहौ\nमदो नैव मे नैव मात्सर्यभावः।\nन धर्मो न चार्थो न कामो न मोक्षः\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मुझमें न द्वेष है न राग, न लोभ न मोह, न घमंड न ईर्ष्या; मैं धर्म, अर्थ, काम या मोक्ष भी नहीं — मैं चेतना और आनंद रूप शिव हूँ।"),
 (S,"न पुण्यं न पापं न सौख्यं न दुःखं\nन मन्त्रो न तीर्थं न वेदा न यज्ञाः।\nअहं भोजनं नैव भोज्यं न भोक्ता\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मैं न पुण्य हूँ न पाप, न सुख न दुख, न मंत्र, तीर्थ, वेद या यज्ञ; न भोजन, न भोजन की वस्तु, न खाने वाला — मैं चेतना और आनंद रूप शिव हूँ।"),
 (S,"न मे मृत्युशंका न मे जातिभेदः\nपिता नैव मे नैव माता न जन्म।\nन बन्धुर्न मित्रं गुरुर्नैव शिष्यः\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मुझे न मृत्यु का डर है, न जाति का भेद; न मेरे पिता हैं, न माता, न जन्म; न भाई, न मित्र, न गुरु, न शिष्य — मैं चेतना और आनंद रूप शिव हूँ।"),
 (S,"अहं निर्विकल्पो निराकाररूपो\nविभुत्वाच्च सर्वत्र सर्वेन्द्रियाणाम्।\nन चासंगतं नैव मुक्तिर्न मेयः\nचिदानन्दरूपः शिवोऽहम् शिवोऽहम्॥","मैं विकल्पों से परे और निराकार हूँ, सर्वव्यापक होकर सब इंद्रियों में हूँ; मैं न बंधा हूँ, न मुक्ति हूँ, न मापा जा सकता हूँ — मैं चेतना और आनंद रूप शिव हूँ।"),
]

GAYATRI = [
 (S,"ॐ भूर्भुवः स्वः।\nतत्सवितुर्वरेण्यं\nभर्गो देवस्य धीमहि।\nधियो यो नः प्रचोदयात्॥",
  "हम उस प्राण-स्वरूप, दुख-नाशक, सुख-स्वरूप, श्रेष्ठ, तेजस्वी, पापनाशक, दिव्य परमात्मा (सविता) का ध्यान करते हैं; वह हमारी बुद्धि को सही मार्ग पर प्रेरित करें।"),
]
MAHAMRITYUNJAY = [
 (S,"ॐ त्र्यम्बकं यजामहे\nसुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान्\nमृत्योर्मुक्षीय माऽमृतात्॥",
  "हम तीन नेत्रों वाले शिव की पूजा करते हैं, जो सुगंधित हैं और सबका पोषण बढ़ाते हैं। जैसे पका हुआ खीरा बेल से अपने आप छूट जाता है, वैसे ही हमें मृत्यु के बंधन से मुक्त करें, अमरता (मोक्ष) से नहीं।"),
]
MANTRA_SANGRAH = [
 ("mantra","श्री गणेश मंत्र\nवक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥","हे टेढ़ी सूँड़ और विशाल शरीर वाले, करोड़ों सूर्यों जैसे तेजस्वी गणेश, मेरे सब कामों को सदा बिना विघ्न के पूरा कीजिए। (हर काम की शुरुआत में)"),
 ("mantra","शिव पंचाक्षर मंत्र\nॐ नमः शिवाय॥","मैं शिव को नमन करता हूँ। शिव का सबसे सरल और शक्तिशाली मंत्र; 108 बार जाप किया जाता है।"),
 ("mantra","श्री विष्णु ध्यान मंत्र\nशान्ताकारं भुजगशयनं पद्मनाभं सुरेशं\nविश्वाधारं गगनसदृशं मेघवर्णं शुभाङ्गम्।\nलक्ष्मीकान्तं कमलनयनं योगिभिर्ध्यानगम्यं\nवन्दे विष्णुं भवभयहरं सर्वलोकैकनाथम्॥","जो शांत स्वरूप हैं, शेषनाग पर सोते हैं, जिनकी नाभि में कमल है, जो देवताओं के स्वामी, विश्व के आधार, आकाश जैसे व्यापक, बादल जैसे साँवले हैं — लक्ष्मीपति, कमल-नयन, योगियों के ध्यान में आने वाले, संसार का भय हरने वाले विष्णु को मैं नमन करता हूँ।"),
 ("mantra","श्री कृष्ण मंत्र\nवसुदेवसुतं देवं कंसचाणूरमर्दनम्।\nदेवकीपरमानन्दं कृष्णं वन्दे जगद्गुरुम्॥","वसुदेव के पुत्र, कंस और चाणूर का नाश करने वाले, देवकी के परम आनंद, जगद्गुरु श्रीकृष्ण को मैं नमन करता हूँ।"),
 ("mantra","श्री राम मंत्र\nश्री राम जय राम जय जय राम॥","श्रीराम की जय — तेरह अक्षरों का यह तारक मंत्र सबसे सरल राम-नाम जाप है।"),
 ("mantra","हनुमान ध्यान मंत्र\nमनोजवं मारुततुल्यवेगं जितेन्द्रियं बुद्धिमतां वरिष्ठम्।\nवातात्मजं वानरयूथमुख्यं श्रीरामदूतं शरणं प्रपद्ये॥","मन जैसी गति और वायु जैसे वेग वाले, इंद्रियों को जीतने वाले, बुद्धिमानों में श्रेष्ठ, पवनपुत्र, वानर सेना के प्रमुख, श्रीराम के दूत की मैं शरण लेता हूँ।"),
 ("mantra","दुर्गा मंत्र\nया देवी सर्वभूतेषु शक्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में शक्ति के रूप में बसती हैं, उन्हें बार-बार नमस्कार है।"),
 ("mantra","सरस्वती वंदना\nया कुन्देन्दुतुषारहारधवला या शुभ्रवस्त्रावृता\nया वीणावरदण्डमण्डितकरा या श्वेतपद्मासना।\nया ब्रह्माच्युतशंकरप्रभृतिभिर्देवैः सदा वन्दिता\nसा मां पातु सरस्वती भगवती निःशेषजाड्यापहा॥","जो कुंद के फूल, चंद्रमा और बर्फ़ जैसी सफ़ेद हैं, सफ़ेद वस्त्र पहनती हैं, हाथ में वीणा है, सफ़ेद कमल पर बैठती हैं, जिन्हें ब्रह्मा, विष्णु और शिव सदा वंदन करते हैं — सारी जड़ता दूर करने वाली वे भगवती सरस्वती मेरी रक्षा करें।"),
 ("mantra","महालक्ष्मी मंत्र\nॐ श्रीं महालक्ष्म्यै नमः॥","महालक्ष्मी को नमन। धन, सुख और समृद्धि के लिए जपा जाने वाला बीज मंत्र।"),
 ("mantra","शांति मंत्र\nॐ सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।\nसर्वे भद्राणि पश्यन्तु मा कश्चिद्दुःखभाग्भवेत्॥\nॐ शान्तिः शान्तिः शान्तिः॥","सब सुखी हों, सब रोगमुक्त हों, सब शुभ देखें, कोई भी दुखी न हो। ॐ शांति, शांति, शांति।"),
]
